pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 value) public {
        vm.assume(value <= c.balanceOf(address(this)));
        uint256 supplyBefore = c.totalSupply();
        c.burn(value);
        uint256 supplyAfter = c.totalSupply();
        assertTrue(supplyAfter <= supplyBefore, "totalSupply should not increase after burn");
    }
}

