pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 _value) public {
        vm.assume(_value > 0);
        uint256 supplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(address(this));
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", _value));
        if (!success) return;
        uint256 supplyAfter = c.totalSupply();
        uint256 balanceAfter = c.balanceOf(address(this));
        assertTrue(supplyAfter == supplyBefore - (balanceBefore - balanceAfter) && supplyAfter <= supplyBefore);
    }
}

