import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 initialBalance, uint256 burnValue) public {
        vm.assume(caller != address(0));
        vm.deal(caller, 0);
        vm.prank(caller);
        uint256 mintAmount = initialBalance;
        c.mintToken(caller, mintAmount);
        uint256 totalSupplyBefore = c.totalSupply();
        vm.prank(caller);
        bool success = false;
        try c.burn(burnValue) {
            success = true;
        } catch {
            success = false;
        }
        if (success) {
            assertTrue(c.totalSupply() == totalSupplyBefore - burnValue);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 initialSupply, string memory tokenName, string memory tokenSymbol, uint256 burnValue) public {
        // Restrict initialSupply so totalSupply fits in uint256 after multiplication
        vm.assume(initialSupply <= 1e30);
        // Restrict tokenName and tokenSymbol to reasonable strings
        vm.assume(bytes(tokenName).length <= 64);
        vm.assume(bytes(tokenSymbol).length <= 8);
        // Deploy C with the fuzzed parameters
        c = new C(initialSupply, tokenName, tokenSymbol);
        // Bound burnValue to a valid amount: not more than caller's balance (which is totalSupply)
        uint256 totalSupplyBefore = c.totalSupply();
        vm.assume(burnValue <= totalSupplyBefore);
        // Record totalSupply before burn
        uint256 totalSupplyBeforeBurn = c.totalSupply();
        // Call burn
        c.burn(burnValue);
        // Assert totalSupply decreased by burnValue
        assertTrue(c.totalSupply() == totalSupplyBeforeBurn - burnValue);
    }
}

