pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 initialSupply, uint256 burnValue) public {
        // Ensure initialSupply and burnValue are reasonable
        vm.assume(initialSupply > 0 && initialSupply <= 1e30);
        vm.assume(burnValue > 0 && burnValue <= initialSupply);
        // Deploy a fresh C with the given initialSupply
        c = new C(initialSupply, "T", "T");

        // Record state before burn
        uint256 totalSupplyBefore = c.totalSupply();
        uint256 callerBalanceBefore = c.balanceOf(address(this));

        // Perform burn
        c.burn(burnValue);

        // Get state after burn
        uint256 totalSupplyAfter = c.totalSupply();
        uint256 callerBalanceAfter = c.balanceOf(address(this));

        // General rule: totalSupplyAfter must be strictly less than totalSupplyBefore + callerBalanceBefore
        // In the reference, totalSupply decreases by burnValue and callerBalance decreases by burnValue
        // So totalSupplyAfter = totalSupplyBefore - burnValue, callerBalanceAfter = callerBalanceBefore - burnValue
        // totalSupplyBefore + callerBalanceBefore - totalSupplyAfter = totalSupplyBefore + callerBalanceBefore - (totalSupplyBefore - burnValue) = callerBalanceBefore + burnValue > 0
        // In the mutant, totalSupply increases by burnValue, so totalSupplyAfter = totalSupplyBefore + burnValue, callerBalanceAfter = callerBalanceBefore - burnValue
        // Then totalSupplyBefore + callerBalanceBefore - totalSupplyAfter = totalSupplyBefore + callerBalanceBefore - (totalSupplyBefore + burnValue) = callerBalanceBefore - burnValue which can be 0
        assertTrue(totalSupplyBefore + callerBalanceBefore > totalSupplyAfter);
    }
}

