pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(caller != address(0));
        // Mint enough to caller to test burn
        vm.prank(c.owner());
        c.mintToken(caller, amount);
        // Record state before burn
        uint256 supplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(caller);
        // Attempt burn via caller
        vm.prank(caller);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", balanceBefore));
        if (ok) {
            uint256 supplyAfter = c.totalSupply();
            // General rule: totalSupply decreased by exactly balanceBefore (the burned amount)
            assertTrue(supplyAfter == supplyBefore - balanceBefore);
        } else {
            // If burn reverts, totalSupply unchanged
            assertTrue(c.totalSupply() == supplyBefore);
        }
    }
}

