pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 value) public {
        vm.assume(value <= type(uint256).max / 2);
        // Mint some tokens first
        address owner = c.owner();
        c.mintToken(owner, value * 2);
        uint256 supplyBefore = c.totalSupply();

        // Try to burn value
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", value));

        if (success) {
            uint256 supplyAfter = c.totalSupply();
            // Reference: burn only succeeds when balance >= value, so totalSupply decreases by exactly value
            assertTrue(supplyAfter <= supplyBefore - value);
        } else {
            // Revert case: supply unchanged
            assertTrue(c.totalSupply() == supplyBefore);
        }
    }
}

