pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount) public {
        vm.assume(burnAmount <= 100_000_000);
        vm.assume(burnAmount <= c.balanceOf(c.owner()));

        // Record sum of all balances before burn
        uint256 sumBefore = c.balanceOf(c.owner()) + c.totalSupply() - c.balanceOf(c.owner());
        sumBefore = c.totalSupply(); // simpler: totalSupply equals sum of balances by construction

        c.burn(burnAmount);

        // After burn, totalSupply must equal sum of balances
        address[] memory accounts = new address[](1);
        accounts[0] = c.owner();
        uint256 sumAfter = c.balanceOf(c.owner());
        // Since we can't enumerate all accounts, the invariant is: totalSupply == sum of all balances
        // We can check a weaker invariant: after burn, totalSupply must be >= balanceOf(owner)
        // Because all tokens belong to owner initially, this catches the bug
        assertTrue(c.totalSupply() >= c.balanceOf(c.owner()) - burnAmount);
        // Actually the invariant: totalSupply == balanceOf(owner) after any operation (since only one holder)
        assertTrue(c.totalSupply() == c.balanceOf(c.owner()));
    }
}

