pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 amount, address other, uint256 otherBalance) public {
        amount = bound(amount, 1, type(uint256).max);
        otherBalance = bound(otherBalance, 0, type(uint256).max);
        vm.assume(other != address(0) && other != caller);
        vm.deal(caller, 1 ether);
        vm.deal(other, 1 ether);

        // Set up initial balances via mintToken (onlyOwner, so prank as owner)
        vm.prank(c.owner());
        c.mintToken(caller, amount + otherBalance);
        vm.prank(c.owner());
        c.mintToken(other, otherBalance);

        // Transfer some to other so caller can burn
        vm.prank(caller);
        c.transfer(other, otherBalance);

        uint256 supplyBefore = c.totalSupply();
        uint256 callerBalBefore = c.balanceOf(caller);

        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", amount));
        if (!success) {
            // burn reverts if caller balance < amount; skip
            return;
        }

        uint256 supplyAfter = c.totalSupply();
        uint256 callerBalAfter = c.balanceOf(caller);
        uint256 otherBalAfter = c.balanceOf(other);

        assertTrue(supplyAfter == callerBalAfter + otherBalAfter);
    }
}

