            success = true;
        } catch {
            success = false;
        }
        // The rule: if burn didn't revert, it must return true; if it reverted, return value is irrelevant
        // For non-revert case, the return value is always true in reference, but may be false in mutant
        // Since we cannot directly get the return value from try/catch, we check the emitted event or balance change
        // Instead, we use a simple invariant: the totalSupply does not increase after a successful burn
        // But the rule states we must use the public surface. The simplest general rule: 
        // When burn succeeds (does not revert), the totalSupply decreases by _value.
        // However, that is not directly about the return value. Let's stick to the return value constraint:
        // We can use vm.recordLogs to capture the Burn event? No, that's too complex.
        // Alternative: we can check that the owner's balance decreased by _value and totalSupply decreased.
        // But the instruction says the assertion must be a general rule that the reference satisfies and mutant breaks, 
        // and the difference is the return value. 
        // The only way to check return value in Solidity test is to call the function and capture the bool return.
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.burn.selector, _value));
        bool reverted = !ok;
        // For the reference, when burn succeeds (ok), it returns true. For mutant, it returns false.
        // But we cannot check the return value from a low-level call. So we must use a high-level call.
        // Use try/catch with the return value captured via a helper? Not possible without modifying contract.
        // Revert to the simplest: We'll just check that the balance and totalSupply update correctly, 
        // but that doesn't capture the return value difference. 
        // Since this is impossible to test the return value difference without the contract returning it, 
        // and the problem says P and M differ in return value, we must assert that the return value is true.
        // We can call burn and check the returned bool directly:
        bool returned = c.burn(_value);
        assertTrue(returned == true);
