import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount) public {
        vm.assume(burnAmount <= c.balanceOf(address(this)));
        uint256 supplyBefore = c.totalSupply();
        c.burn(burnAmount);
        uint256 supplyAfter = c.totalSupply();
        assertTrue(supplyAfter == supplyBefore - burnAmount);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount) public {
        // Ensure burnAmount is within reasonable bounds (no overflow)
        vm.assume(burnAmount <= type(uint256).max / 2);
        uint256 supplyBefore = c.totalSupply();
        // Try to burn; if it reverts, the rule holds trivially
        try c.burn(burnAmount) {
            // If burn succeeds, check that supply did not increase
            assertTrue(c.totalSupply() >= supplyBefore - burnAmount && c.totalSupply() <= supplyBefore);
        } catch {
            // Revert means no change; supply unchanged
            assertTrue(c.totalSupply() == supplyBefore);
        }
    }
}

