pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 mintAmount) public {
        uint256 initialTotal = c.totalSupply();
        c.mintToken(address(this), mintAmount);
        uint256 finalTotal = c.totalSupply();
        assertTrue(finalTotal == initialTotal + mintAmount, "mintToken should increase totalSupply by mintedAmount");
    }
}

