pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address burner, uint256 amount) public {
        vm.assume(burner != address(0));
        c.mintToken(burner, amount);
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(burner);
        c.burn(amount);
        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(burner);
        assertTrue(totalBefore - totalAfter == balAfter - balBefore);
    }
}

