pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnValue) public {
        vm.assume(burnValue > 0 && burnValue <= 10_000_000 ether);
        uint256 initialTotal = c.totalSupply();
        uint256 initialBalance = c.balanceOf(address(this));
        vm.assume(initialBalance >= burnValue);
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnValue));
        if (success) {
            uint256 finalBalance = c.balanceOf(address(this));
            uint256 finalTotal = c.totalSupply();
            assertTrue(finalBalance + finalTotal >= initialTotal);
        } else {
            assertTrue(false);
        }
    }
}

