pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount, address target, uint256 mintAmount) public {
        vm.assume(burnAmount <= 1000000000000000000000000000);
        vm.assume(mintAmount <= 1000000000000000000000000000);
        vm.assume(target != address(0));

        // Mint and then burn
        c.mintToken(target, mintAmount);
        uint256 balanceBefore = c.balanceOf(target);
        vm.assume(burnAmount <= balanceBefore);
        c.burn(burnAmount);

        // The general rule: after burning, the target's balance must be >= 0
        assertTrue(c.balanceOf(target) >= 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount) public {
        vm.assume(burnAmount > 0 && burnAmount <= c.balanceOf(address(this)));
        uint256 preBalance = c.balanceOf(address(this));
        uint256 preTotalSupply = c.totalSupply();
        c.burn(burnAmount);
        uint256 postBalance = c.balanceOf(address(this));
        uint256 postTotalSupply = c.totalSupply();
        assertTrue(preBalance + preTotalSupply == postBalance + postTotalSupply + burnAmount);
    }
}
